using System;using System.IO;using System.Linq;using System.Reflection;using System.Drawing;using System.Collections.Generic;using System.Threading;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class LatestImportUiTests {
 static int count;static void Check(bool b,string t){if(!b)throw new Exception(t);count++;Console.WriteLine("OK "+t);}
 static object Field(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static void Set(object o,string n,object value){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,value);}
 static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}
 static void Pump(){Application.DoEvents();Thread.Sleep(10);}
 static void Wait(Controller c){var end=DateTime.UtcNow.AddSeconds(30);while((bool)Field(c,"busy")&&DateTime.UtcNow<end)Pump();Check(!(bool)Field(c,"busy"),"Asynchroner Import vollständig abgeschlossen");Pump();}
 static Project Five(string input){var p=new Project();for(int i=0;i<5;i++)p.Folders.Add(new BoxFolder{Name=(30+i).ToString("D3")+" Country",Theme="Country",Songs=new List<Song>{new Song{Source=input,Artist="Alt",Title="Country "+i,Album="Country"}}});return p;}
 [STAThread]static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string input=Path.GetFullPath(args[1]);var before=File.ReadAllBytes(input);string dir=Path.Combine(root,"Neue Musik");Directory.CreateDirectory(dir);string a=Path.Combine(dir,"Sunflower.mp3"),b=Path.Combine(dir,"Wildflowers.mp3");MediaMetadata.WriteCopy(new Song{Source=input,Artist="Glen Campbell",Title="Sunflower"},"Neue Musik",a,()=>{});MediaMetadata.WriteCopy(new Song{Source=input,Artist="Lainey Wilson",Title="Wildflowers and Wild Horses"},"Neue Musik",b,()=>{});
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var v=new MainView(Path.Combine(root,"layout.json"))){var c=new Controller(v,Path.Combine(root,"backups"),new Playback(new PlaybackTestDevice()));var old=Five(input);Call(c,"ReplaceProject",old,null,true);v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1525,784);Pump();Check(v.Folders.Items.Count==5&&v.Songs.Rows.Count==5,"Ausgangssituation: fünf Country-Ordner geladen");
   v.Songs.Rows[0].Selected=true;v.Songs.CurrentCell=v.Songs.Rows[0].Cells[0];v.InvokeCommand("Abspielen");Set(c,"playlistOrder",old.Folders.SelectMany(f=>f.Songs).ToList());((AudioInputSelection)Field(c,"gainInputs")).Add(new[]{input},()=>{});v.SearchBox.Text="Country";Set(c,"libraryFolder",old.Folders[0]);Set(c,"groupField","artist");Set(c,"groupValue","Alt");
   int dialogs=Application.OpenForms.Count;v.ReceiveFileDrop(v.Songs,new[]{a,b},0);Wait(c);var current=(Project)Field(c,"p");Check(current.Folders.SelectMany(f=>f.Songs).Count()==2&&v.Songs.Rows.Count==2&&v.Folders.Items.Count==1,"Nach echtem Drop-Pfad bleiben nur die zwei neuen Titel und ihr neuer Ordner");Check(v.SearchBox.Text==""&&v.LibraryMode=="Titel"&&Field(c,"libraryFolder")==null&&Field(c,"groupField")==null,"Alte Such- und Ordnerfilter verdecken keine neuen Titel");Check(Field(c,"playerSong")==null&&Field(c,"playlistOrder")==null&&((AudioInputSelection)Field(c,"gainInputs")).Songs.Count==0,"Player und alte Arbeitsauswahlen verweisen nicht mehr auf entfernte Titel");Check(Application.OpenForms.Count==dialogs,"Erfolgreicher Import zeigt keinen alten Nummerierungshinweis");
   string saved=Path.Combine(root,"latest.musikbox.json");Storage.Save(current,saved);Check(Storage.Load(saved).Folders.SelectMany(f=>f.Songs).Count()==2,"Gespeichertes Projekt enthält ebenfalls nur den letzten Import");v.InvokeCommand("Rückgängig");Check(v.Folders.Items.Count==5&&((Project)Field(c,"p")).Folders.Count==5,"Ersetzung kann wie andere Bibliotheksänderungen rückgängig gemacht werden");
   // Exercise the real folder picker command, including repeated source imports.
   v.SelectStudioPage("Konvertierung");
   using(var choose=new System.Windows.Forms.Timer{Interval=30}){choose.Tick+=(s,e)=>{var picker=Application.OpenForms.OfType<AppFolderDialog>().FirstOrDefault();if(picker==null)return;choose.Stop();picker.NameInput.Text=dir;Check(picker.AcceptSelection(),"Ordnerdialog bestätigt die neue Quelle");};choose.Start();v.InvokeCommand("Ordner laden");Wait(c);}
   Check(((Project)Field(c,"p")).Folders.SelectMany(f=>f.Songs).Count()==2&&v.Songs.Rows.Count==2,"Ordnerauswahl verwendet dieselbe Ersetzungsregel");Check(!v.ModuleHost.Visible&&v.Songs.Visible,"Nach Import wird die neue Bibliothek auch aus einem Werkzeugmodul heraus angezeigt");
   using(var choose=new System.Windows.Forms.Timer{Interval=30}){choose.Tick+=(s,e)=>{var picker=Application.OpenForms.OfType<AppFolderDialog>().FirstOrDefault();if(picker==null)return;choose.Stop();picker.NameInput.Text=dir;picker.AcceptSelection();};choose.Start();v.InvokeCommand("Ordner laden");Wait(c);}
   Check(v.Songs.Rows.Count==2&&((Project)Field(c,"p")).Folders.Sum(f=>f.Songs.Count)==2,"Erneute Auswahl desselben Ordners wird eingelesen und nicht übersprungen/angehängt");
   using(var dismiss=new System.Windows.Forms.Timer{Interval=30}){dismiss.Tick+=(s,e)=>{foreach(var form in Application.OpenForms.Cast<Form>().Where(f=>f!=v).ToArray())if(form is StudioReportView||form is MessageView)form.Close();};dismiss.Start();var prior=Field(c,"p");v.ReceiveFileDrop(v.Songs,new[]{Path.Combine(root,"fehlt.mp3")},-1);Wait(c);Check(Object.ReferenceEquals(prior,Field(c,"p"))&&v.Songs.Rows.Count==2,"Ungültiger Drop lässt die aktuelle Bibliothek sichtbar");v.ReceiveFileDrop(v.Songs,new[]{a,b},-1);((System.Threading.CancellationTokenSource)Field(c,"cancel")).Cancel();Wait(c);Check(Object.ReferenceEquals(prior,Field(c,"p"))&&v.Songs.Rows.Count==2,"Abbruch lässt die aktuelle Bibliothek sichtbar");dismiss.Stop();}
   var configured=(Project)Field(c,"p");configured.ReencodeMp3=true;configured.FfmpegExecutable="/usr/bin/ffmpeg";v.ReceiveFileDrop(v.Songs,new[]{a,b},-1);Wait(c);Check(((Project)Field(c,"p")).Folders.SelectMany(f=>f.Songs).All(s=>ImportAudio.Ready((Project)Field(c,"p"),s)),"Automatische Audioverarbeitung erfasst alle neuen Titel trotz vorheriger Ordner");Check(v.Songs.Rows.Count==2,"Verarbeiteter neuer Import bleibt allein sichtbar");
   using(var dismiss=new System.Windows.Forms.Timer{Interval=30}){dismiss.Tick+=(s,e)=>{foreach(var form in Application.OpenForms.Cast<Form>().Where(f=>f!=v).ToArray())if(form is StudioReportView||form is MessageView)form.Close();};dismiss.Start();var prior=Field(c,"p");((Project)prior).FfmpegExecutable="/bin/false";v.ReceiveFileDrop(v.Songs,new[]{a,b},-1);Wait(c);Check(Object.ReferenceEquals(prior,Field(c,"p"))&&v.Songs.Rows.Count==2,"Fehlgeschlagene Audioverarbeitung übernimmt keinen unvollständigen Import");dismiss.Stop();}
   Check(before.SequenceEqual(File.ReadAllBytes(input))&&File.Exists(a)&&File.Exists(b),"Import-Ersetzung löscht keine Quelldateien");Set(c,"dirty",false);v.Close();
  }
  Console.WriteLine("BESTANDEN: "+count+" Import-UI-Prüfungen; Mono/Xvfb, keine Windows-Abnahme.");
 }
}
